function validate([word]) {
  if (typeof word !== 'string' || word.length < 1 || word.length > 500000) return 'word needs 1 to 500000 characters.';
  if (!/^[aeiou]+$/.test(word)) return 'word may contain only the vowels a, e, i, o and u.';
  return null;
}

