function longestBeautifulSubstring(word) {
  let best = 0;
  let left = 0;
  let distinct = 1;
  for (let right = 1; right < word.length; right++) {
    if (word[right] < word[right - 1]) {
      left = right;
      distinct = 1;
    } else if (word[right] > word[right - 1]) {
      distinct++;
    }
    if (distinct === 5) {
      best = Math.max(best, right - left + 1);
    }
  }
  return best;
}

