function longestBeautifulSubstring(word) {
  let best = 0;
  for (let i = 0; i < word.length; i++) {
    for (let j = i; j < word.length; j++) {
      const piece = word.slice(i, j + 1);
      const sorted = piece.split('').sort().join('');
      if (sorted === piece && new Set(piece).size === 5) best = Math.max(best, piece.length);
    }
  }
  return best;
}

