function generate(rand, size) {
  const vowels = 'aeiou';
  const target = size === 'large' ? 8000 + Math.floor(rand() * 2001) : 1 + Math.floor(rand() * 24);
  const maxRun = size === 'large' ? 1 + Math.floor(rand() * 30) : 1 + Math.floor(rand() * 3);
  let word = '';
  while (word.length < target) {
    if (rand() < 0.2) {
      word += vowels[Math.floor(rand() * 5)];
      continue;
    }
    // An ordered run that starts at some vowel, may skip one, and may stop early.
    let v = rand() < 0.6 ? 0 : Math.floor(rand() * 5);
    const last = rand() < 0.6 ? 4 : v + Math.floor(rand() * (5 - v));
    for (; v <= last; v++) {
      if (rand() < 0.08) continue;
      word += vowels[v].repeat(1 + Math.floor(rand() * maxRun));
    }
  }
  return [word.slice(0, target)];
}
